"use client";

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/context/AuthContext';
import Sidebar from '@/components/Sidebar';
import TopBar from '@/components/TopBar';
import PlayerBar from '@/components/PlayerBar';
import HomeView from '@/views/HomeView';
import SearchView from '@/views/SearchView';
import PlaylistView from '@/views/PlaylistView';
import LyricsView from '@/views/LyricsView';
import DashboardView from '@/views/DashboardView';
import DownloadsView from '@/views/DownloadsView';
import AiPlaylistView from '@/views/AiPlaylistView';
import LoginPage from '@/views/LoginPage';
import ImportModal from '@/components/ImportModal';
import { getTokenFromUrl } from '@/services/spotify';
import { Playlist } from '@/types/music';

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const handler = () => setIsMobile(window.innerWidth < 768);
    handler();
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);

  return isMobile;
}

export default function App() {
  const { currentUser } = useAuth();
  const isMobile = useIsMobile();
  const [mounted, setMounted] = useState(false);

  const [activeView, setActiveView] = useState<string>("home");
  const [activePlaylist, setActivePlaylist] = useState<Playlist | null>(null);
  const [search, setSearch] = useState<string>("");
  const [spotifyToken, setSpotifyToken] = useState<string | null>(null);
  const [isDemo, setIsDemo] = useState(false);

  useEffect(() => {
    setMounted(true);
    try {
      const savedView = localStorage.getItem("soundify_active_view");
      if (savedView) setActiveView(savedView);

      const demo = localStorage.getItem("demo_mode") === "true";
      setIsDemo(demo);

      const token = getTokenFromUrl();
      if (token) {
        localStorage.setItem("spotify_token", token);
        setSpotifyToken(token);
      } else {
        const existingToken = localStorage.getItem("spotify_token");
        if (existingToken) setSpotifyToken(existingToken);
      }
    } catch (e) {
      console.warn("Could not read localStorage:", e);
    }
  }, []);

  const saveActiveView = (view: string) => {
    setActiveView(view);
    try {
      localStorage.setItem("soundify_active_view", view);
    } catch {}
  };

  const saveActivePlaylist = (playlist: Playlist | null) => {
    setActivePlaylist(playlist);
    try {
      if (playlist?.id) {
        localStorage.setItem("soundify_active_playlist", playlist.id);
      } else {
        localStorage.removeItem("soundify_active_playlist");
      }
    } catch {}
  };

  // SSR hydration safety
  if (!mounted) {
    return (
      <div style={{ height: '100vh', width: '100vw', background: '#030914', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ width: 40, height: 40, borderRadius: '50%', border: '3px solid #00D2FF', borderTopColor: 'transparent', animation: 'spin 1s linear infinite' }} />
      </div>
    );
  }

  // Login / Demo gate
  if (!currentUser && !isDemo) {
    return <LoginPage />;
  }

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: isMobile ? "1fr" : "var(--sidebar-width) 1fr",
        gridTemplateRows: isMobile ? "1fr auto auto" : "1fr var(--player-height)",
        gridTemplateAreas: isMobile
          ? `"main" "player" "sidebar"`
          : `"sidebar main" "player player"`,
        height: "100vh",
        width: "100vw",
        background: "var(--wx-bg)",
        color: "var(--wx-text)",
        fontFamily: "var(--font-family)",
        overflow: "hidden",
      }}
    >
      {/* Sidebar */}
      <div style={{ gridArea: "sidebar", overflow: "hidden" }}>
        <Sidebar
          activeView={activeView}
          setActiveView={saveActiveView}
          activePlaylist={activePlaylist}
          setActivePlaylist={saveActivePlaylist}
        />
      </div>

      {/* Main content area */}
      <div
        style={{
          gridArea: "main",
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
          background: "radial-gradient(ellipse 80% 60% at 70% 0%, #0a1e3d 0%, var(--wx-bg) 60%)",
          minWidth: 0,
        }}
      >
        {/* TopBar */}
        <TopBar
          activeView={activeView}
          search={search}
          setSearch={(v: string) => {
            setSearch(v);
            if (v && activeView !== "search") saveActiveView("search");
          }}
        />

        {/* Scrollable View Content */}
        <div
          style={{
            flex: 1,
            overflowY: "auto",
            overflowX: "hidden",
            animation: "fadeInUp 0.35s ease",
            paddingBottom: isMobile ? 140 : 0,
          }}
        >
          {activeView === "home" && (
            <HomeView
              setActiveView={saveActiveView}
              setActivePlaylist={saveActivePlaylist}
            />
          )}

          {activeView === "search" && (
            <SearchView search={search} onSearchChange={(v: string) => { setSearch(v); }} />
          )}

          {activeView === "lyrics" && <LyricsView />}
          {activeView === "dashboard" && <DashboardView />}
          {activeView === "downloads" && <DownloadsView setActiveView={saveActiveView} />}
          {activeView === "ai" && <AiPlaylistView />}

          {(activeView === "liked" || activeView === "playlist") && (
            <PlaylistView
              activeView={activeView}
              activePlaylist={activePlaylist}
              setActivePlaylist={saveActivePlaylist}
              setActiveView={saveActiveView}
            />
          )}
        </div>
      </div>

      {/* Player Bar */}
      <div style={{ gridArea: "player" }}>
        <PlayerBar
          activeView={activeView}
          setActiveView={saveActiveView}
          activePlaylist={activePlaylist}
          setActivePlaylist={saveActivePlaylist}
        />
      </div>

      {/* Spotify Import Modal */}
      {spotifyToken && (
        <ImportModal
          token={spotifyToken}
          onClose={() => setSpotifyToken(null)}
        />
      )}
    </div>
  );
}

